package glitch

import data.glitch_lib

# Weak encryption algorithms
weak_algorithms := {"DES", "3DES", "RC2", "RC4", "Blowfish", "IDEA", "CAST5", "SEED", "Rabbit"}

# Weak hash functions when used for encryption
weak_hashes := {"MD5", "SHA1"}

# Weak TLS/SSL versions
weak_tls_versions := {"TLS1.0", "TLS_1_0", "TLS1.1", "TLS_1_1", "SSLv2", "SSLv3", "TLSv1"}

# Weak cipher suite indicators
weak_cipher_indicators := {"NULL", "EXPORT", "DES", "3DES", "RC4", "_anon_", "ALLOW_ALL"}

# Weak block cipher modes
weak_block_modes := {"ECB", "Electronic Codebook"}

# Weak RSA key sizes
weak_rsa_sizes := {512, 768, 1024}

# Weak elliptic curves
weak_curves := {"secp160", "secp192", "P-192", "P-224", "brainpoolP160"}

# Weak DH/DSA groups
weak_dh_groups := {"Group 1", "Group 2", "MODP-768", "MODP-1024"}

# Encryption-related attribute names
encryption_attrs := {
    "encryption_at_rest",
    "server_side_encryption",
    "kms_key_id",
    "customer_managed_key",
    "transparent_data_encryption",
    "disk_encryption",
    "volume_encryption",
    "snapshot_encryption",
    "backup_encryption",
    "key_specification",
    "key_usage",
    "customer_key_spec",
    "key_length",
    "key_size",
    "bits",
    "rsa_key_version",
    "elliptic_curve",
    "curve_name",
    "certificate_authority",
    "tls_version_min",
    "tls_cipher_policy",
    "security_policy",
    "ssl_policy",
    "minimum_protocol_version",
    "policy_identifier",
    "storage_encrypted",
    "enable_encryption",
    "encrypted",
    "sse_algorithm",
    "kms_master_key_id",
    "tde_key_identifier",
    "algorithm",
    "cipher",
    "mode",
    "encryption",
    "tls_policy",
    "cipher_suite"
}

# Check if value contains weak algorithm
contains_weak_algorithm(value) {
    value.ir_type == "String"
    alg := weak_algorithms[_]
    regex.match(sprintf("(?i).*%s.*", [alg]), value.value)
}

# Check if value contains weak hash
contains_weak_hash(value) {
    value.ir_type == "String"
    hash := weak_hashes[_]
    regex.match(sprintf("(?i).*%s.*", [hash]), value.value)
}

# Check if value contains weak TLS version
contains_weak_tls_version(value) {
    value.ir_type == "String"
    ver := weak_tls_versions[_]
    regex.match(sprintf("(?i).*%s.*", [ver]), value.value)
}

# Check if value contains weak cipher indicator
contains_weak_cipher_indicator(value) {
    value.ir_type == "String"
    ind := weak_cipher_indicators[_]
    regex.match(sprintf("(?i).*%s.*", [ind]), value.value)
}

# Check if value contains weak block mode
contains_weak_block_mode(value) {
    value.ir_type == "String"
    mode := weak_block_modes[_]
    regex.match(sprintf("(?i).*%s.*", [mode]), value.value)
}

# Check if value is a weak RSA key size
is_weak_rsa_size(value) {
    value.ir_type == "Integer"
    weak_rsa_sizes[value.value]
}

# Check if value contains weak curve
contains_weak_curve(value) {
    value.ir_type == "String"
    curve := weak_curves[_]
    regex.match(sprintf("(?i).*%s.*", [curve]), value.value)
}

# Check if value contains weak DH group
contains_weak_dh_group(value) {
    value.ir_type == "String"
    group := weak_dh_groups[_]
    regex.match(sprintf("(?i).*%s.*", [group]), value.value)
}

# Check string value for encryption weakness
check_encryption_weakness(value) {
    contains_weak_algorithm(value)
} else {
    contains_weak_hash(value)
} else {
    contains_weak_tls_version(value)
} else {
    contains_weak_cipher_indicator(value)
} else {
    contains_weak_block_mode(value)
} else {
    contains_weak_curve(value)
} else {
    contains_weak_dh_group(value)
}

# Check integer value for encryption weakness
check_encryption_weakness_int(value) {
    is_weak_rsa_size(value)
}

# Recursively check expressions for encryption weaknesses
has_encryption_weakness(expr) {
    expr.ir_type == "String"
    check_encryption_weakness(expr)
} else {
    expr.ir_type == "Integer"
    check_encryption_weakness_int(expr)
} else {
    expr.ir_type == "Array"
    item := expr.value[_]
    has_encryption_weakness(item)
} else {
    expr.ir_type == "Hash"
    val := expr.value[_]
    has_encryption_weakness(val)
}

# Check if attribute name indicates encryption context
is_encryption_attr(name) {
    attr := encryption_attrs[_]
    regex.match(sprintf("(?i).*%s.*", [attr]), name)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_encryption_attr(attr.name)
    has_encryption_weakness(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - The resource uses weak encryption algorithms, insufficient key lengths, or deprecated cryptographic protocols. (CWE-326)"
    }
}

