package glitch

import data.glitch_lib

weak_algorithms := {"DES", "3DES", "RC2", "RC4", "Blowfish", "IDEA", "CAST5", "SEED", "Rabbit"}

weak_hashes := {"MD5", "SHA1", "md5_crypt", "sha1_crypt"}

weak_tls_versions := {"TLS1.0", "TLS_1_0", "TLS1.1", "TLS_1_1", "SSLv2", "SSLv3", "TLSv1"}

weak_cipher_indicators := {"NULL", "EXPORT", "DES", "3DES", "RC4", "_anon_", "ALLOW_ALL", "CBC_SHA"}

weak_block_modes := {"ECB", "Electronic Codebook"}

weak_rsa_sizes := {512, 768, 1024}

weak_curves := {"secp160", "secp192", "P-192", "P-224", "brainpoolP160"}

weak_dh_groups := {"Group 1", "Group 2", "MODP-768", "MODP-1024"}

encryption_attr_patterns := {
    "encryption",
    "cipher",
    "tls",
    "ssl",
    "key",
    "hash",
    "algorithm",
    "mode",
    "curve",
    "encrypt",
    "decrypt",
    "sig",
    "hmac",
    "sha",
    "md5",
    "aes",
    "rsa",
    "des",
    "3des",
    "rc4",
    "blowfish",
    "ecdsa",
    "diffie",
    "dh_group",
    "kex",
    "mac",
    "protocol"
}

check_string_weakness(str_value) {
    alg := weak_algorithms[_]
    regex.match(sprintf("(?i)(^|[^a-zA-Z])%s([^a-zA-Z]|$)", [alg]), str_value)
} else {
    hash := weak_hashes[_]
    regex.match(sprintf("(?i)(^|[^a-zA-Z])%s([^a-zA-Z]|$)", [hash]), str_value)
} else {
    ver := weak_tls_versions[_]
    regex.match(sprintf("(?i)%s", [ver]), str_value)
} else {
    ind := weak_cipher_indicators[_]
    regex.match(sprintf("(?i)%s", [ind]), str_value)
} else {
    mode := weak_block_modes[_]
    regex.match(sprintf("(?i)(^|[^a-zA-Z])%s([^a-zA-Z]|$)", [mode]), str_value)
} else {
    curve := weak_curves[_]
    regex.match(sprintf("(?i)%s", [curve]), str_value)
} else {
    group := weak_dh_groups[_]
    regex.match(sprintf("(?i)%s", [group]), str_value)
}

is_encryption_related_attr(name) {
    pattern := encryption_attr_patterns[_]
    regex.match(sprintf("(?i).*%s.*", [pattern]), name)
}

is_weak_value(node) {
    node.ir_type == "String"
    check_string_weakness(node.value)
} else {
    node.ir_type == "Integer"
    weak_rsa_sizes[node.value]
}

has_weakness_in_expr(expr) {
    _ := [true |
        walk(expr, [_, node])
        is_weak_value(node)
    ][_]
}

check_key_value_pair(key, value) {
    is_encryption_related_attr(key)
    has_weakness_in_expr(value)
}

extract_key_string(key_expr) = str {
    key_expr.ir_type == "String"
    str := key_expr.value
} else = str {
    key_expr.ir_type == "VariableReference"
    str := key_expr.value
}

check_hash_entry(entry) {
    key_str := extract_key_string(entry.key)
    check_key_value_pair(key_str, entry.value)
}

check_array_element(elem) {
    elem.ir_type == "Hash"
    entry := elem.value[_]
    check_hash_entry(entry)
} else {
    has_weakness_in_expr(elem)
}

# Check function calls for weak crypto (e.g., hash('sha1'))
is_weak_function_call(node) {
    node.ir_type == "FunctionCall"
    func_name_lower := lower(node.name)
    contains(func_name_lower, "hash")
    arg := node.args[_]
    arg.ir_type == "String"
    hash := weak_hashes[_]
    lower(arg.value) == hash
} else {
    node.ir_type == "FunctionCall"
    func_name_lower := lower(node.name)
    contains(func_name_lower, "encrypt")
    arg := node.args[_]
    arg.ir_type == "String"
    check_string_weakness(arg.value)
}

check_any_expr(expr) {
    is_weak_value(expr)
} else {
    is_weak_function_call(expr)
} else {
    expr.ir_type == "Array"
    elem := expr.value[_]
    check_array_element(elem)
} else {
    expr.ir_type == "Hash"
    entry := expr.value[_]
    check_hash_entry(entry)
} else {
    walk(expr, [_, node])
    is_weak_value(node)
} else {
    walk(expr, [_, node])
    is_weak_function_call(node)
}

# Get all key-value pairs from node (attributes, variables, etc.)
all_key_values(node) = kvs {
    kvs = {{"key": k, "value": v, "container": container} |
        walk(node, [path, container])
        container.ir_type == "Attribute"
        k := container.name
        v := container.value
    }
}

all_key_values(node) = kvs {
