        walk(node, [path, container])
        container.ir_type == "Variable"
        k := container.name
        v := container.value
    }
}

all_key_values(node) = kvs {
    kvs = {{"key": k, "value": v, "container": container} |
        walk(node, [path, attr])
        attr.ir_type == "Attribute"
        attr.value.ir_type == "Array"
        arr_elem := attr.value.value[_]
